-- Таблица: Мои подключения (входящие подключения к сервисам МТЗСН)
CREATE TABLE IF NOT EXISTS my_connections (
    id               BIGSERIAL PRIMARY KEY,
    connection_date  TIMESTAMP,
    service_key      VARCHAR(255) NOT NULL,
    service_owner    TEXT,
    is_owner         TEXT,
    is_client_mtzn   TEXT,
    smart_bridge_ticket VARCHAR(50)
);
